<?php require_once __DIR__.'/../includes/security.php';require __DIR__.'/../includes/db.php';require __DIR__.'/../includes/customer-auth.php';if(current_customer()){header('Location: ../account.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$pw=$_POST['password']??'';if(mb_strlen($name)<2||mb_strlen($name)>120||!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190||!preg_match('/^[0-9+(). -]{6,30}$/',$phone)||strlen($pw)<12||strlen($pw)>200){$error='Periksa kembali data. Kata sandi minimal 12 karakter.';}else{try{$s=$pdo->prepare('INSERT INTO customers(name,email,phone,password_hash) VALUES(?,?,?,?)');$s->execute([$name,$email,$phone,password_hash($pw,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();session_regenerate_id(true);$_SESSION['customer']=['id'=>$id,'name'=>$name,'email'=>$email,'phone'=>$phone];header('Location: ../account.php');exit;}catch(PDOException $e){if($e->getCode()==='23000')$error='Email sudah digunakan. Silakan masuk.';else throw $e;}}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daftar akun — TokoKita</title><link rel="stylesheet" href="../assets/style.css"><style>.auth{max-width:500px;margin:40px auto;padding:26px}.auth .field{margin:14px 0}</style></head><body><?php include __DIR__.'/../includes/header.php'?><?php customer_nav()?><main class="wrap"><form class="panel auth" method="post"><span class="eyebrow">TOKOKITA</span><h1 class="page-title">Buat akun pelanggan</h1><p class="muted">Simpan alamat agar checkout berikutnya lebih cepat. Akun ini hanya untuk pemesanan di toko.</p><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Nama lengkap</label><input name="name" maxlength="120" required value="<?=e($_POST['name']??'')?>"></div><div class="field"><label>Email</label><input type="email" name="email" maxlength="190" autocomplete="email" required value="<?=e($_POST['email']??'')?>"></div><div class="field"><label>Telepon</label><input name="phone" maxlength="30" autocomplete="tel" required value="<?=e($_POST['phone']??'')?>"></div><div class="field"><label>Kata sandi (minimal 12 karakter)</label><input type="password" name="password" minlength="12" maxlength="200" autocomplete="new-password" required></div><button class="btn full">Daftar dan lanjut belanja</button><p>Sudah punya akun? <a href="login.php">Masuk</a></p></form></main><?php include __DIR__.'/../includes/footer.php'?></body></html>